```javascript
// 1. 在公共总线注册拉取回调（一次性）
const task = eda.sys_MessageBus.pullPublic('嘉立创示例_公共拉取', (message) => {
  console.log('公共总线拉到：', message);
});

// 2. 用 pushPublic 投递消息，回调立即触发
eda.sys_MessageBus.pushPublic('嘉立创示例_公共拉取', '公共任务甲');

// 3. 取消任务，恢复原状
task.cancel();
console.log('已取消公共拉取任务');
```
